-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/outlands/Trial_by_Fire.lua"]={["Path"]="scripts/quests/outlands/Trial_by_Fire.lua",["SHA256"]="3f6972fbe2c210004d5c1c7647b10e59377c0f5e83698eb16642fd134068680f",["Text"]="-----------------------------------\n-- Trial by Fire\n-----------------------------------\n-- Log ID: 5, Quest ID: 12\n-- !addquest 5 12\n-- Ronta-Onta : !pos 100.370 -13.999 -97.676 250\n-- Dodmos     : !pos 102.647 -13.999 -97.664 250\n-----------------------------------\n-- Event 273 hides the pact option (bit 5) for players who have not unlocked SMN.\n-----------------------------------\nlocal kazhamID = zones[xi.zone.KAZHAM]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_FIRE)\n\nquest.reward =\n{\n    fame     = 60,\n    fameArea = xi.fameArea.WINDURST,\n}\n\nlocal rewardItems =\n{\n    [0] = xi.item.IFRITS_BLADE,\n    [1] = xi.item.FIRE_BELT,\n    [2] = xi.item.FIRE_RING,\n    [3] = xi.item.EGILS_TORCH,\n}\n\nlocal function getRewardMask(player)\n    local rewardMask = 0\n\n    for bitNum, itemId in pairs(rewardItems) do\n        if player:hasItem(itemId) then\n            rewardMask = utils.mask.setBit(rewardMask, bitNum, true)\n        end\n    end\n\n    if player:hasSpell(xi.magic.spell.IFRIT) or not player:hasJob(xi.job.SMN) then\n        rewardMask = utils.mask.setBit(rewardMask, 5, true)\n    end\n\n    return rewardMask\nend\n\nlocal function giveQuestReward(player, eventOption)\n    local wasRewarded = true\n\n    if eventOption <= 4 then\n        wasRewarded = npcUtil.giveItem(player, rewardItems[eventOption - 1])\n    elseif eventOption == 5 then\n        npcUtil.giveCurrency(player, 'gil', 10000)\n    elseif eventOption == 6 then\n        player:addSpell(xi.magic.spell.IFRIT)\n        player:messageSpecial(kazhamID.text.IFRIT_UNLOCKED, 0, 0, 0)\n    end\n\n    return wasRewarded\nend\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 6\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            -- Fourth event param plays the injured researcher introduction only seen before the first completion.\n            ['Ronta-Onta'] = quest:progressEvent(270, 0, xi.keyItem.TUNING_FORK_OF_FIRE, 0, 1),\n\n            onEventFinish =\n            {\n                [270] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_FIRE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Dodmos'] = quest:event(272),\n\n            ['Ronta-Onta'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.WHISPER_OF_FLAMES) then\n                        return quest:progressEvent(273, 0, 1, 0, 0, getRewardMask(player))\n                    elseif not player:hasKeyItem(xi.keyItem.TUNING_FORK_OF_FIRE) then\n                        -- Player has failed the BCNM and requires a new Tuning Fork.\n                        return quest:progressEvent(285, 0, xi.keyItem.TUNING_FORK_OF_FIRE)\n                    else\n                        return quest:event(271, 4, xi.keyItem.TUNING_FORK_OF_FIRE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [273] = function(player, csid, option, npc)\n                    -- Retail does not advance the quest on an escaped cutscene.\n                    if option < 1 or option > 6 then\n                        return\n                    end\n\n                    if giveQuestReward(player, option) then\n                        quest:complete(player)\n                        player:delKeyItem(xi.keyItem.WHISPER_OF_FLAMES)\n                        quest:setTimedVar(player, 'Timer', NextJstDay())\n                    end\n                end,\n\n                [285] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_FIRE)\n                end,\n            },\n        },\n\n        [xi.zone.CLOISTER_OF_FLAMES] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.TRIAL_BY_FIRE then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WHISPER_OF_FLAMES)\n                        player:addTitle(xi.title.HEIR_OF_THE_GREAT_FIRE)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Ronta-Onta'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Repeatable once per JST day.\n                    if quest:getVar(player, 'Timer') == 0 then\n                        return quest:progressEvent(270, 0, xi.keyItem.TUNING_FORK_OF_FIRE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [270] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_BY_FIRE)\n\n                        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_FIRE)\n\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Wandering_Souls.lua"]={["Path"]="scripts/quests/outlands/Wandering_Souls.lua",["SHA256"]="c509f0d921a2e6fd274804fc339d43656eb14a91ba836f895201909fda973aaf",["Text"]="-----------------------------------\n-- Wandering Souls\n-----------------------------------\n-- Log ID: 5, Quest ID: 161\n-- Cermet Headstone : !pos -107 -8 450 113\n-----------------------------------\nlocal terigganID = zones[xi.zone.CAPE_TERIGGAN]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.WANDERING_SOULS)\n\nquest.reward =\n{\n    item  = xi.item.FLAGELLANTS_ROPE,\n    title = xi.title.BEARER_OF_BONDS_BEYOND_TIME,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CAPE_TERIGGAN] =\n        {\n            ['Cermet_Headstone'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.RAIN_LILY) then\n                        return quest:progressEvent(202, xi.item.RAIN_LILY)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:messageSpecial(terigganID.text.MUST_BE_A_WAY_TO_SOOTHE)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [202] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/Wrath_of_the_Opo_Opos.lua"]={["Path"]="scripts/quests/outlands/Wrath_of_the_Opo_Opos.lua",["SHA256"]="43780fcb599e7f7d56270f612db320dd3caa347cfa78c0bd8eaeae05b1554a80",["Text"]="-----------------------------------\n-- Wrath of the Opo-Opos\n-----------------------------------\n-- Log ID: 5, Quest ID: 160\n-- Cermet Headstone : !pos 491 20 301 123\n-----------------------------------\nlocal yuhtungaID = zones[xi.zone.YUHTUNGA_JUNGLE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.WRATH_OF_THE_OPO_OPOS)\n\nquest.reward =\n{\n    item  = xi.item.OPO_OPO_NECKLACE,\n    title = xi.title.FRIEND_OF_THE_OPO_OPOS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.YUHTUNGA_JUNGLE] =\n        {\n            ['Cermet_Headstone'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.GARNET) then\n                        return quest:progressEvent(202, xi.item.GARNET)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:messageSpecial(yuhtungaID.text.TOUCHING_RED_JEWEL)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [202] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/outlands/You_Call_That_a_Knife.lua"]={["Path"]="scripts/quests/outlands/You_Call_That_a_Knife.lua",["SHA256"]="753be2a88a50fa1be1f27304d8ab6429ec3b6f7723d985a5f4225ad704c45c4a",["Text"]="-----------------------------------\n-- You Call That a Knife\n-----------------------------------\n-- Log ID: 5, Quest ID: 6\n-- Mhebi Juhbily : !pos 40 -11 -159 250\n-- Vah Keshura   : !pos 30 -8.5 -105 250\n-- Chef Nonberry : !pos -136 0.0 -91 159\n-- Pula Rhatti   : !pos -18.5 -4 -38 250\n-----------------------------------\nlocal templeID = zones[xi.zone.TEMPLE_OF_UGGALEPIH]\n-----------------------------------\n\n---@type TQuest\nlocal quest = Quest:new(xi.questLog.OUTLANDS, xi.quest.id.outlands.YOU_CALL_THAT_A_KNIFE)\n\nquest.reward =\n{\n    fame     = 60,\n    fameArea = xi.fameArea.WINDURST,\n    gil      = 7200,\n    title    = xi.title.YA_DONE_GOOD\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 6\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Mhebi_Juhbily'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        npcUtil.tradeHasExactly(trade, { xi.item.SANDFISH })\n                    then\n                        return quest:progressEvent(127, 0, xi.item.SANDFISH)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:event(318)\n                    end\n                end\n            },\n\n            ['Pula_Rhatti'] = quest:event(269, 0, xi.item.SANDFISH),\n\n            ['_6y9'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(128)\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [127] = function(player, csid, option, npc)\n                    if option == 511 then\n                        quest:setVar(player, 'Prog', 1)\n                        player:confirmTrade()\n                    end\n                end,\n\n                [128] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                not player:hasKeyItem(xi.keyItem.NONBERRYS_KNIFE)\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Mhebi_Juhbily'] = quest:event(129),\n\n            ['Pula_Rhatti'] = quest:event(269, 0, xi.item.SANDFISH),\n\n            ['Vah_Keshura'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(130)\n                    else\n                        return quest:event(131)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [130] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end\n            },\n        },\n\n        [xi.zone.TEMPLE_OF_UGGALEPIH] =\n        {\n            ['Chef_Nonberry'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.TONBERRY_BOARD }) then\n                        return quest:progressEvent(27)\n                    else\n                        return quest:progressEvent(28)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [27] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.NONBERRYS_KNIFE)\n                end,\n\n                [28] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    local cookMobs = {\n                        templeID.mob.COOK_OFFSET,\n                        templeID.mob.COOK_OFFSET + 1,\n                        templeID.mob.COOK_OFFSET + 2,\n                        templeID.mob.COOK_OFFSET + 3\n                    }\n                    if\n                        GetSystemTime() >= npc:getLocalVar('cooldown') and\n                        npcUtil.popFromQM(player, npc, cookMobs, { claim = true, hide = 0 })\n                    then\n                        npc:setLocalVar('cooldown', GetSystemTime() + 600) -- 10 minutes between repops\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasKeyItem(xi.keyItem.NONBERRYS_KNIFE)\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Mhebi_Juhbily'] = quest:progressEvent(133),\n\n            ['Vah_Keshura'] = quest:event(132),\n\n            onEventFinish =\n            {\n                [133] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.NONBERRYS_KNIFE)\n                        quest:setMustZone(player)\n                    end\n                end\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                quest:getMustZone(player)\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Mhebi_Juhbily'] = quest:event(134),\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Mhebi_Juhbily'] = quest:event(135),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/A_Job_for_the_Consortium.lua"]={["Path"]="scripts/quests/sandoria/A_Job_for_the_Consortium.lua",["SHA256"]="1b6144732ce39eaa20059fa4578f67afdc0bda6f24970f8c1b58ee916ae03440",["Text"]="-----------------------------------\n-- A Job for the Consortium\n-----------------------------------\n-- Log ID: 0, Quest ID: 67\n-----------------------------------\n-- Portaure :      !pos -22 -4 -106 232\n-- _6u2 :          !pos -61.0 6.451 57.998\n-- Haubijoux :     !pos -61 8 58 246\n-- Yin Pocanakhu : !pos 35 4 -46 245\n-----------------------------------\nlocal juenoPortID  = zones[xi.zone.PORT_JEUNO]\nlocal lowerID = zones[xi.zone.LOWER_JEUNO]\nlocal sandyPortID = zones[xi.zone.PORT_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_JOB_FOR_THE_CONSORTIUM)\n\nlocal packageCondition =\n{\n    NORMAL      = 0,\n    CONFISCATED = 1,\n    DAMAGED     = 2,\n}\n\nlocal checkSmuggle = function()\n    local caughtSmuggling = false\n    local hour = VanadielHour()\n\n    if\n        hour > 5 and\n        hour < 18 and\n        math.randomInt(1, 100) <= 25\n    then\n        caughtSmuggling = true\n    end\n\n    return caughtSmuggling\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return vars.Stage == 0 and\n                quest:getVar(player, 'Option') == 0 and\n                player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_JOB_FOR_THE_CONSORTIUM) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Portaure'] = quest:event(571):importantOnce(), -- This is a single time dialogue. It only ever plays once and is never seen again.\n\n            onEventFinish =\n            {\n                [571] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return vars.Stage == 0 and\n                player:hasKeyItem(xi.keyItem.TENSHODO_MEMBERS_CARD) and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 5 and\n                player:getFameLevel(xi.fameArea.NORG) >= 1\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Portaure'] =\n            {\n                onTrigger = function(player, npc)\n                    local firstTime = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_JOB_FOR_THE_CONSORTIUM) == xi.questStatus.QUEST_AVAILABLE and 0 or 1\n\n                    if player:getVar('[AIRSHIP]suspended') >= GetSystemTime() then\n                        return quest:messageText(sandyPortID.text.LAY_LOW)\n                    else\n                        return quest:event(651, { [0] = firstTime })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [651] = function(player, csid, option, npc)\n                    if option == 1 and npcUtil.giveKeyItem(player, xi.keyItem.BRUGAIRE_GOODS) then\n                        quest:begin(player)\n                        -- Set as damaged, going through customs reverses it.\n                        quest:setVar(player, 'Prog', packageCondition.DAMAGED)\n                        quest:setVar(player, 'Stage', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return vars.Stage == 1 and\n            player:hasKeyItem(xi.keyItem.BRUGAIRE_GOODS)\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Portaure'] = quest:event(652),\n        },\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['_6u2'] =\n            {\n                onTrigger = function(player, npc)\n                    local caught = checkSmuggle()\n                    local param = 0\n\n                    if caught then\n                        quest:setVar(player, 'Prog', packageCondition.CONFISCATED)\n                        param = 1\n                    end\n\n                    return quest:progressEvent(54, param)\n                end,\n            },\n\n            ['Haubijoux'] =\n            {\n                onTrigger = function(player, npc)\n                    local caught = checkSmuggle()\n                    local param = 0\n\n                    if caught then\n                        quest:setVar(player, 'Prog', packageCondition.CONFISCATED)\n                        param = 1\n                    end\n\n                    return quest:progressEvent(54, param)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [54] = function(player, csid, option, npc)\n                    if option == 1 then\n                        if quest:getVar(player, 'Prog') == packageCondition.CONFISCATED then\n                            player:delKeyItem(xi.keyItem.BRUGAIRE_GOODS)\n                            player:setVar('[AIRSHIP]suspended', JstMidnight())\n                            player:messageSpecial(juenoPortID.text.CONFISCATED, xi.keyItem.BRUGAIRE_GOODS)\n                        else\n                            player:messageSpecial(juenoPortID.text.CLEARED_CUSTOMS)\n                            quest:setVar(player, 'Prog', packageCondition.NORMAL)\n                        end\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Yin_Pocanakhu'] =\n            {\n                onTrigger = function(player, npc)\n                    local damaged = quest:getVar(player, 'Prog') == packageCondition.DAMAGED and true or false\n\n                    if damaged then\n                        return quest:progressEvent(218)\n                    else\n                        return quest:progressEvent(219)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [218] = function(player, csid, option, npc)\n                    player:messageSpecial(lowerID.text.DAMANGED_PACKAGE_DELIVERED, xi.keyItem.BRUGAIRE_GOODS)\n                    player:delKeyItem(xi.keyItem.BRUGAIRE_GOODS)\n                end,\n\n                [219] = function(player, csid, option, npc)\n                    player:messageSpecial(lowerID.text.PACKAGE_DELIVERED, xi.keyItem.BRUGAIRE_GOODS)\n                    player:delKeyItem(xi.keyItem.BRUGAIRE_GOODS)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return vars.Stage == 1 and\n            not player:hasKeyItem(xi.keyItem.BRUGAIRE_GOODS)\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Portaure'] =\n            {\n                onTrigger = function(player, npc)\n                    local result = quest:getVar(player, 'Prog')\n                    -- 0 delivered, 1 = confiscated, 2 = damaged\n                    return quest:progressEvent(653 + result)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [653] = function(player, csid, option, npc)\n                    quest:complete(player)\n                    npcUtil.giveCurrency(player, 'gil', 1000)\n                    player:addFame(xi.fameArea.NORG, 20)\n                end,\n\n                [654] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n                [655] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    -- Actions for Airship travels in Jeuno when suspended.\n    {\n        check = function(player, status, vars)\n            return player:getVar('[AIRSHIP]suspended') >= GetSystemTime()\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['_6u4'] = quest:event(42):setPriority(200), -- Sandy\n            ['_6u8'] = quest:event(41):setPriority(200), -- Kazahm\n            ['_6ua'] = quest:event(40):setPriority(200), -- Bastok\n            ['_6ue'] = quest:event(43):setPriority(200), -- Windurst\n            ['Illauvolahaut'] = quest:event(41):setPriority(200), -- Kazahm\n            ['Omiro-Zamiro']  = quest:event(43):setPriority(200), -- Windurst\n            ['Purequane']     = quest:event(42):setPriority(200), -- Sandy\n            ['Zedduva']       = quest:event(40):setPriority(200), -- Bastok\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/A_Knights_Test.lua"]={["Path"]="scripts/quests/sandoria/A_Knights_Test.lua",["SHA256"]="a4815e0e95ab9f9accdaa4b820a45ea8bb5e58cf2f896fd6fe1ad938160d6cf2",["Text"]="-----------------------------------\n-- A Knight's Test\n-----------------------------------\n-- Log ID: 0, Quest ID: 29\n-- Balasiel     : !pos -136 -11 64 230\n-- Cahaurme     : !pos 55.749 -8.601 -29.354 230\n-- Baunise      : !pos -55 -8 -32 230\n-- Disused Well : !pos -221 2 -293 149\n-----------------------------------\nlocal davoiID            = zones[xi.zone.DAVOI]\nlocal southernSandoriaID = zones[xi.zone.SOUTHERN_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_KNIGHTS_TEST)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.KITE_SHIELD,\n    keyItem  = xi.keyItem.JOB_GESTURE_PALADIN,\n    title    = xi.title.TRIED_AND_TESTED_KNIGHT,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_SQUIRES_TEST_II)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Balasiel'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL then\n                        if quest:getVar(player, 'Option') == 0 then\n                            return quest:progressEvent(627)\n                        else\n                            return quest:progressEvent(635)\n                        end\n                    else\n                        return quest:event(670)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [627] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.BOOK_OF_TASKS)\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n\n                [635] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.BOOK_OF_TASKS)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Balasiel'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.KNIGHTS_SOUL) then\n                        return quest:progressEvent(628)\n                    else\n                        return quest:event(669)\n                    end\n                end,\n            },\n\n            ['Baunise'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.BOOK_OF_THE_WEST) then\n                        return quest:progressEvent(634)\n                    else\n                        return quest:messageName(southernSandoriaID.text.DO_NOT_FRET)\n                    end\n                end,\n            },\n\n            ['Cahaurme'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.BOOK_OF_THE_EAST) then\n                        return quest:progressEvent(633)\n                    else\n                        return quest:messageName(southernSandoriaID.text.TRIAL_IS_DIFFICULT)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [628] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:unlockJob(xi.job.PLD)\n                        player:messageSpecial(southernSandoriaID.text.UNLOCK_PALADIN)\n\n                        player:delKeyItem(xi.keyItem.KNIGHTS_SOUL)\n                        player:delKeyItem(xi.keyItem.BOOK_OF_TASKS)\n                        player:delKeyItem(xi.keyItem.BOOK_OF_THE_WEST)\n                        player:delKeyItem(xi.keyItem.BOOK_OF_THE_EAST)\n                    end\n                end,\n\n                [633] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BOOK_OF_THE_EAST)\n                end,\n\n                [634] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BOOK_OF_THE_WEST)\n                end,\n            },\n        },\n\n        [xi.zone.DAVOI] =\n        {\n            ['Disused_Well'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.BOOK_OF_THE_EAST) and\n                        player:hasKeyItem(xi.keyItem.BOOK_OF_THE_WEST)\n                    then\n                        if not player:hasKeyItem(xi.keyItem.KNIGHTS_SOUL) then\n                            return quest:keyItem(xi.keyItem.KNIGHTS_SOUL)\n                        else\n                            return quest:messageSpecial(davoiID.text.YOU_FIND_NOTHING)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Baunise']  = quest:messageName(southernSandoriaID.text.YOUVE_DONE_WELL):replaceDefault(),\n            ['Cahaurme'] = quest:messageName(southernSandoriaID.text.MAKE_EXCELLENT_KNIGHT):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/A_Purchase_of_Arms.lua"]={["Path"]="scripts/quests/sandoria/A_Purchase_of_Arms.lua",["SHA256"]="9e4851bfa5080098dd245f9db10f80218e17f1dd60562f02d51da0874fc4d41e",["Text"]="-----------------------------------\n-- A Purchase of Arms\n-----------------------------------\n-- Log ID: 0, Quest ID: 27\n-----------------------------------\n-- Helbort : !pos 71 -1 65 230\n-- Alexius : !pos 105 1 382 104\n-----------------------------------\nlocal forestID = zones[xi.zone.JUGNER_FOREST]\nlocal southID  = zones[xi.zone.SOUTHERN_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_PURCHASE_OF_ARMS)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.ELM_STAFF,\n    title    = xi.title.ARMS_TRADER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.FATHER_AND_SON) == xi.questStatus.QUEST_COMPLETED and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 2\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Helbort'] = quest:progressEvent(594),\n\n            onEventFinish =\n            {\n                [594] = function(player, csid, option, npc)\n                    if option == 0 and npcUtil.giveKeyItem(player, xi.keyItem.WEAPONS_ORDER) then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasKeyItem(xi.keyItem.WEAPONS_ORDER)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Helbort'] = quest:message(southID.text.HELBORT_ORDERS),\n        },\n\n        [xi.zone.JUGNER_FOREST] =\n        {\n            ['Alexius'] = quest:progressEvent(5),\n\n            onEventFinish =\n            {\n                [5] = function(player, csid, option, npc)\n                    if npcUtil.giveKeyItem(player, xi.keyItem.WEAPONS_RECEIPT) then\n                        player:delKeyItem(xi.keyItem.WEAPONS_ORDER)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                not player:hasKeyItem(xi.keyItem.WEAPONS_ORDER)\n        end,\n\n        [xi.zone.JUGNER_FOREST] =\n        {\n            ['Alexius'] = quest:messageName(forestID.text.ALEXIUS_ORDERS, xi.keyItem.WEAPONS_RECEIPT, 0, 0, 0, true, false),\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Helbort'] = quest:progressEvent(607),\n\n            onEventFinish =\n            {\n                [607] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.WEAPONS_RECEIPT)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Helbort'] = quest:message(southID.text.HELBORT_ORDERS + 3)\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/A_Sentrys_Peril.lua"]={["Path"]="scripts/quests/sandoria/A_Sentrys_Peril.lua",["SHA256"]="49478acef2c7d2f79625d95c759b69d9d9ce679ef252142da812abc9203e5b69",["Text"]="-----------------------------------\n-- A Sentry's Peril\n-- Glenne - Southern Sandoria, !pos -122 -2 15 230\n-- Aaveleon - West Ronfaure, !pos -431 -45 343 100\n-----------------------------------\nlocal westRonfaureID = zones[xi.zone.WEST_RONFAURE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_SENTRYS_PERIL)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    title = xi.title.RONFAURIAN_RESCUER,\n    item = xi.item.BRONZE_SUBLIGAR,\n}\n\nquest.sections =\n{\n    -- Talk to Glenne; she's worried about her husband, Aaveleon, a guard out on patrol, and gives you some healing ointment to take to him.\n    {\n        check = function(player, status)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Glenne'] = quest:progressEvent(510),\n\n            onEventFinish =\n            {\n                [510] = function(player, csid, option, npc)\n                    if option == 0 and npcUtil.giveItem(player, xi.item.DOSE_OF_OINTMENT) then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        }\n    },\n\n    -- Find him on the road to Ghelsba Outpost in West Ronfaure (G-6).\n    -- Trade Ointment to him and he'll give you the Ointment Case, so you can give it back to his wife.\n    {\n        check = function(player, status)\n            return status == xi.questStatus.QUEST_ACCEPTED and quest:getVar(player, 'TradedAaveleon') == 0\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Glenne'] =\n            {\n                onTrade = function(player, npc, trade)\n                    return quest:event(514) -- \"I cannot accept this. Take it back.\"\n                end,\n\n                onTrigger = function(player, npc)\n                    if player:hasItem(xi.item.DOSE_OF_OINTMENT) then\n                        return quest:event(520) -- reminder to deliver ointment\n                    else\n                        return quest:progressEvent(644) -- reacquire ointment\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [644] = function(player, csid, option, npc)\n                    npcUtil.giveItem(player, xi.item.DOSE_OF_OINTMENT)\n                end,\n            },\n        },\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Aaveleon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.DOSE_OF_OINTMENT) then\n                        if player:getFreeSlotsCount() == 0 then\n                            return quest:event(118) -- \"Ah...but it seems you're already carrying too much.\"\n                        else\n                            return quest:progressEvent(100)\n                        end\n                    else\n                        return quest:event(106) -- \"What's this? I can't accept gifts from strangers.\"\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [100] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.OINTMENT_CASE) then\n                        player:confirmTrade()\n                        quest:setVar(player, 'TradedAaveleon', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Trade the Ointment Case to Glenne to complete the quest.\n    {\n        check = function(player, status)\n            return status == xi.questStatus.QUEST_ACCEPTED and quest:getVar(player, 'TradedAaveleon') == 1\n        end,\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Aaveleon'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasItem(xi.item.OINTMENT_CASE) then\n                        return quest:message(westRonfaureID.text.AAVELEON_HEALED) -- \"My wounds are healed, thanks to you!\"\n                    else\n                        return quest:progressEvent(126, xi.item.OINTMENT_CASE) -- reacquire ointment case\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [126] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveItem(player, xi.item.OINTMENT_CASE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Glenne'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(520) -- reminder to deliver ointment\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.OINTMENT_CASE) then\n                        return quest:progressEvent(513)\n                    else\n                        return quest:event(514) -- \"I cannot accept this. Take it back.\"\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [513] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: After quest completion\n    {\n        check = function(player, status)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Glenne'] = quest:event(521),\n        },\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Aaveleon'] = quest:message(westRonfaureID.text.AAVELEON_HEALED),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/A_Squires_Test.lua"]={["Path"]="scripts/quests/sandoria/A_Squires_Test.lua",["SHA256"]="b600885e41b4ebd2b81c097afd6c7298a1c18ed6ca3c65e6e65d4830dc87a987",["Text"]="-----------------------------------\n-- A Squire's Test\n-----------------------------------\n-- Log ID: 0, Quest ID: 10\n-- Balasiel : !pos -136 -11 64 230\n-----------------------------------\nlocal southernSandoriaID = zones[xi.zone.SOUTHERN_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_SQUIRES_TEST)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.SPATHA,\n    title    = xi.title.KNIGHT_IN_TRAINING,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Balasiel'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(616)\n                    else\n                        return quest:progressEvent(631)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [616] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n\n                [631] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Balasiel'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.REVIVAL_TREE_ROOT) then\n                        return quest:progressEvent(617)\n                    end\n                end,\n\n                onTrigger = quest:messageName(southernSandoriaID.text.GO_TO_KING_RANPERRES, xi.item.REVIVAL_TREE_ROOT),\n            },\n\n            onEventFinish =\n            {\n                [617] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/A_Squires_Test_II.lua"]={["Path"]="scripts/quests/sandoria/A_Squires_Test_II.lua",["SHA256"]="361371d9f163979b7338bcc5397c401ea980297ae9768fd20aebbff2408550c7",["Text"]="-----------------------------------\n-- A Squire's Test II\n-----------------------------------\n-- Log ID: 0, Quest ID: 19\n-- Balasiel : !pos -136 -11 64 230\n-- qm2      : !pos -94 1 273 193\n-- qm3      : !pos -139 0.1 264 193\n-----------------------------------\nlocal ordellesCavesID = zones[xi.zone.ORDELLES_CAVES]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_SQUIRES_TEST_II)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    keyItem  = xi.keyItem.SQUIRE_CERTIFICATE,\n    title    = xi.title.SPELUNKER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_SQUIRES_TEST)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Balasiel'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= 10 then\n                        return quest:progressEvent(625)\n                    else\n                        return quest:event(671)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [625] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Balasiel'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.STALACTITE_DEW) then\n                        return quest:progressEvent(626)\n                    else\n                        return quest:event(630)\n                    end\n                end,\n            },\n\n            ['Chanpau'] = quest:event(629),\n\n            onEventFinish =\n            {\n                [626] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.STALACTITE_DEW)\n                    end\n                end,\n\n                [629] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n            },\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Morjean'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:event(602)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.ORDELLES_CAVES] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.STALACTITE_DEW) then\n                        quest:setVar(player, 'Timer', GetSystemTime() + 30)\n                    end\n\n                    return quest:messageSpecial(ordellesCavesID.text.PLACE_HANDS_IN_POOL)\n                end,\n            },\n\n            ['qm3'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.STALACTITE_DEW) then\n                        if GetSystemTime() <= quest:getVar(player, 'Timer') then\n                            return quest:keyItem(xi.keyItem.STALACTITE_DEW)\n                        else\n                            return quest:messageSpecial(ordellesCavesID.text.DEW_SLIPS_THROUGH_FINGERS)\n                        end\n                    else\n                        return quest:messageSpecial(ordellesCavesID.text.ALREADY_OBTAINED_DEW)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/A_Taste_for_Meat.lua"]={["Path"]="scripts/quests/sandoria/A_Taste_for_Meat.lua",["SHA256"]="e967265c794ad5c8d1a96e93ef94a418fd0242c733f34903445067dd4d45d707",["Text"]="-----------------------------------\n-- A Taste for Meat\n-----------------------------------\n-- Log ID: 0, Quest ID: 100\n-- Antreneau : !pos -71 -5 -39 232\n-- Thierride : !pos -67 -5 -28 232\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_TASTE_FOR_MEAT)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    gil = 150,\n    title = xi.title.RABBITER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        -- This entire quest is not flagged; however, the quest is accepted and\n        -- completed in the same step (on trading 5 hare meat after progressing).\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Antreneau'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeHas(trade, xi.item.SLICE_OF_HARE_MEAT)\n                    then\n                        return quest:progressEvent(531)\n                    else\n                        return quest:event(532)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(527)\n                    else\n                        return quest:event(525)\n                    end\n                end,\n            },\n\n            ['Thierride'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeHasExactly(trade, { { xi.item.SLICE_OF_HARE_MEAT, 5 } })\n                    then\n                        return quest:progressEvent(528)\n                    else\n                        return quest:event(529)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(526)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [527] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [528] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n\n                        -- This variable is set after quest has been cleared, and is cleaned\n                        -- up after receiving Grilled Hare item from Antreneau.\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Antreneau'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:progressEvent(530)\n                    end\n                end,\n            },\n\n            ['Thierride'] = quest:event(524):replaceDefault(),\n\n            onEventFinish =\n            {\n                [530] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.SLICE_OF_GRILLED_HARE) then\n                        quest:setVar(player, 'Option', 0)\n                    else\n                        player:startEvent(538)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/A_Timely_Visit.lua"]={["Path"]="scripts/quests/sandoria/A_Timely_Visit.lua",["SHA256"]="e9b3d7e05b018ccec1922fdb63fbf46a49929cf9f110821c54b420c5c333a140",["Text"]="-----------------------------------\n-- A Timely Visit\n-----------------------------------\n-- Log ID: 0, Quest ID: 105\n-- Deraquien !pos -98.698 -2.0 32.056\n-- Narvecaint !pos -261.936 23.144 127.61\n-- Phillone !pos -208.832 -2.949 67.189\n-- qm1 !pos -310.882 -0.139 407.377\n-----------------------------------\nlocal jugnerID = zones[xi.zone.JUGNER_FOREST]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_TIMELY_VISIT)\n\nquest.reward =\n{\n    fame = 40,\n    fameArea = xi.fameArea.SANDORIA,\n    item = xi.item.MEDIEVAL_COLLAR,\n    title = xi.title.OBSIDIAN_STORM,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 4\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Deraquien'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(33)\n                    else\n                        return quest:progressEvent(47)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [33] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Option', 1) -- Player declined to start quest, and flags the secondary dialogue to start quest\n                    end\n                end,\n\n                [47] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Option', 0) -- Resets variable\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Pre NM Fight\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Stage == 0\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Halver'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(112)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [112] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            ['Narvecaint'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:progressEvent(0)\n                    elseif progress <= 2 then\n                        return quest:event(6):setPriority(101)\n                    elseif progress <= 5 then\n                        return quest:event(7):setPriority(101)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Deraquien'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:event(34):setPriority(101)\n                    elseif progress == 1 then\n                        return quest:progressEvent(80)\n                    elseif progress == 2 then\n                        return quest:event(20):setPriority(101)\n                    elseif progress == 3 then\n                        return quest:progressEvent(87)\n                    elseif progress == 4 then\n                        return quest:event(30):setPriority(101)\n                    elseif progress == 5 then\n                        return quest:progressEvent(38)\n                    end\n                end,\n            },\n\n            ['Phillone'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 4 then\n                        return quest:progressEvent(78)\n                    elseif progress == 5 then\n                        return quest:event(91):setPriority(101)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n\n                [38] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Stage', 1)\n                end,\n\n                [78] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n\n                [80] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [87] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    -- NM fight to end\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Stage == 1\n        end,\n\n        [xi.zone.JUGNER_FOREST] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    local hour = VanadielHour()\n                    local progress = quest:getVar(player, 'Prog')\n                    local mobsSpawned = (GetMobByID(jugnerID.mob.GIOLLEMITTE):isSpawned() or GetMobByID(jugnerID.mob.GIOLLEMITTE + 1):isSpawned())\n                    local waitOver = GetSystemTime() >= npc:getLocalVar('Wait')\n                    local isDaytime = (hour >= 6 and hour <= 17)\n\n                    if player:getLocalVar('NMKilled') == 1 and progress == 5 and not mobsSpawned then\n                        return quest:progressEvent(18)\n                    elseif progress == 5 and waitOver and not mobsSpawned and not isDaytime then\n                        for i = 0, 1 do\n                            SpawnMob(jugnerID.mob.GIOLLEMITTE + i):updateClaim(player)\n                        end\n\n                        return quest:messageSpecial(jugnerID.text.SENSE_OF_FOREBODING)\n                    elseif progress == 5 and isDaytime then\n                        return quest:messageSpecial(jugnerID.text.UNABLE_TO_INVESTIGATE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n\n                [18] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n            },\n\n            -- Player can kill EITHER NM to progress\n            ['Giollemitte_B_Feroun'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if\n                        mob:getID() == jugnerID.mob.GIOLLEMITTE and\n                        quest:getVar(player, 'Prog') == 5\n                    then\n                        player:setLocalVar('NMKilled', 1)\n                    end\n                end,\n            },\n\n            -- Player can kill EITHER NM to progress\n            ['Skeleton_Esquire_NM'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if\n                        mob:getID() == jugnerID.mob.GIOLLEMITTE + 1 and\n                        quest:getVar(player, 'Prog') == 5\n                    then\n                        player:setLocalVar('NMKilled', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            ['Narvecaint'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress <= 6 then\n                        return quest:event(7):setPriority(101)\n                    elseif progress == 7 then\n                        return quest:progressEvent(1)\n                    else\n                        return quest:event(8):setPriority(101)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n\n                [1] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 8)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Deraquien'] = quest:event(27):setPriority(101),\n\n            ['Phillone'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress <= 5 then\n                        return quest:event(48):setPriority(101)\n                    elseif progress == 6 then\n                        return quest:progressEvent(21)\n                    elseif progress == 8 then\n                        return quest:progressEvent(14)\n                    else\n                        return quest:event(49):setPriority(101)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n\n                [14] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n                [21] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 7)\n                end,\n            },\n        },\n    },\n\n    {\n    check = function(player, status, vars)\n        return status == xi.questStatus.QUEST_COMPLETED\n    end,\n\n    [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Phillone'] = quest:event(28):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Advanced_Teamwork.lua"]={["Path"]="scripts/quests/sandoria/Advanced_Teamwork.lua",["SHA256"]="52ec4bf43a12e0f48104f01711760abddfc86f1b46a2736b630a669001764aee",["Text"]="-----------------------------------\n-- Advanced Teamwork\n-----------------------------------\n-- Log ID: 0, Quest ID: 65\n-----------------------------------\n-- Vilatroire : !pos -260 -70 423 100\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.ADVANCED_TEAMWORK)\n\nquest.reward =\n{\n    item     = xi.item.HORN_RING,\n    fame     = 40,\n    fameArea = xi.fameArea.SANDORIA,\n    title    = xi.title.FIRST_RATE_ORGANIZER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.INTERMEDIATE_TEAMWORK) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Vilatroire'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getFameLevel(xi.fameArea.SANDORIA) >= 4 and\n                        player:getMainLvl() >= 10\n                    then\n                        return quest:progressEvent(131)\n                    else\n                        return quest:event(130):replaceDefault()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [131] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Vilatroire'] =\n            {\n                onTrigger = function(player, npc)\n                    local party = player:getParty()\n\n                    if #party > 1 then\n                        return quest:progressEvent(129, { [1] = 3 })\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [129] = function(player, csid, option, npc)\n                    local partySizeRequirement = 2\n                    local party = player:getParty()\n                    local partySameJobCount = 0\n\n                    if #party >= partySizeRequirement then\n                        for key, member in pairs(party) do\n                            if\n                                member:getZoneID() ~= player:getZoneID() or\n                                member:checkDistance(player) > 15\n                            then\n                                player:updateEvent(1)\n                                return\n                            else\n                                if player:getMainJob() == member:getMainJob() then\n                                    partySameJobCount = partySameJobCount + 1\n                                end\n                            end\n                        end\n                    else\n                        player:updateEvent(1)\n                        return\n                    end\n\n                    if partySameJobCount == partySizeRequirement then\n                        quest:setLocalVar(player, 'Prog', 1)\n                        player:updateEvent(15, 3)\n                        return\n                    else\n                        player:updateEvent(5, 3)\n                        return\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [129] = function(player, csid, option, npc)\n                    if option == 0 and quest:getLocalVar(player, 'Prog') == 1 then\n                        if quest:complete(player) then\n                            quest:setLocalVar(player, 'Prog', 0)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Vilatroire'] = quest:event(130),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Atellounes_Lament.lua"]={["Path"]="scripts/quests/sandoria/Atellounes_Lament.lua",["SHA256"]="53e072745ed48fc9844812fa53c1a6042912716117b5babcad12be5862d0d54b",["Text"]="-----------------------------------\n-- Atelloune's Lament\n-- !addquest 0 114\n-- Atelloune: !pos 122 0 82 230\n-- LADYBUG_WING: !additem 2506\n-- TRAINEE_GLOVES: !additem 15008\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.ATELLOUNES_LAMENT)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item = xi.item.TRAINEE_GLOVES,\n}\n\nquest.sections =\n{\n    -- Speak to Atelloune in Southern San d'Oria at (L-6) for a cutscene to start the quest.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 2 and\n                player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SEEING_SPOTS) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Atelloune'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(890)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [890] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Trade her a Ladybug Wing for a cutscene and to receive your reward.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Atelloune'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(892)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.LADYBUG_WING) then\n                        return quest:progressEvent(891)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [891] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Black_Tiger_Skins.lua"]={["Path"]="scripts/quests/sandoria/Black_Tiger_Skins.lua",["SHA256"]="85fed2e11633f95338c9a754e7db270b1102638ce3b483d8442e006605dbe264",["Text"]="-----------------------------------\n-- Black Tiger Skins\n-----------------------------------\n-- Log ID: 0, Quest ID: 31\n-- Hanaa Punaa : !pos -179.726 -8.8 27.574 230\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.BLACK_TIGER_SKINS)\n\nquest.reward =\n{\n    fame = 30,\n    fameArea = xi.fameArea.SANDORIA,\n    item = xi.item.TIGER_STOLE,\n    itemParams = { fromTrade = true },\n    title = xi.title.CAT_SKINNER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 3 and\n                player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.LIZARD_SKINS)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hanaa_Punaa'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(576)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(579)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [576] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [579] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hanaa_Punaa'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.TIGER_HIDE, 3 } }) then\n                        return quest:progressEvent(577)\n                    end\n                end,\n\n                onTrigger = quest:progressEvent(578),\n            },\n\n            onEventFinish =\n            {\n                [577] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and player:getFameLevel(xi.fameArea.SANDORIA) >= 3\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hanaa_Punaa'] = quest:event(592):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Blackmail.lua"]={["Path"]="scripts/quests/sandoria/Blackmail.lua",["SHA256"]="d4a289cebb6bf9393283faf6e9c991b7ff620079253c534fbc87ad264d30d14a",["Text"]="-----------------------------------\n-- Blackmail\n-----------------------------------\n-- Log ID: 0, Quest ID: 71\n-----------------------------------\n-- Dauperiat : !pos -20 0 -26 231\n-- Halver    : !pos 2 0 0 233\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.BLACKMAIL)\n\nquest.reward =\n{\n    fame     = 16,\n    fameArea = xi.fameArea.SANDORIA,\n    gil      = 900,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Dauperiat'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getFameLevel(xi.fameArea.SANDORIA) >= 3 and\n                        player:getRank(player:getNation()) >= 3\n                    then\n                        return quest:progressEvent(643)\n                    else\n                        if player:needToZone() then\n                            return quest:event(642)\n                        else\n                            return quest:event(641)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [641] = function(player, csid, option, npc)\n                    player:needToZone(true)\n                end,\n\n                [643] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SUSPICIOUS_ENVELOPE)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasKeyItem(xi.keyItem.SUSPICIOUS_ENVELOPE)\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Dauperiat'] = quest:event(645),\n        },\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Halver'] = quest:progressEvent(549),\n\n            onEventFinish =\n            {\n                [549] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.SUSPICIOUS_ENVELOPE)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog == 1\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Dauperiat'] = quest:progressEvent(646, { [1] = xi.item.COPY_OF_THE_CASTLE_FLOOR_PLANS }),\n\n            onEventFinish =\n            {\n                [646] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog == 2\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Dauperiat'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.COPY_OF_THE_CASTLE_FLOOR_PLANS) then\n                        return quest:progressEvent(648, { [1] = xi.item.COPY_OF_THE_CASTLE_FLOOR_PLANS })\n                    end\n                end,\n\n                onTrigger = quest:event(647, { [1] = xi.item.COPY_OF_THE_CASTLE_FLOOR_PLANS }),\n            },\n\n            onEventFinish =\n            {\n                [648] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                vars.Prog == 0\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Dauperiat'] = quest:progressEvent(650, { [1] = xi.item.COPY_OF_THE_CASTLE_FLOOR_PLANS }),\n\n            onEventFinish =\n            {\n                [650] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                vars.Prog == 1\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Dauperiat'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.COPY_OF_THE_CASTLE_FLOOR_PLANS) then\n                        return quest:progressEvent(648, { [1] = xi.item.COPY_OF_THE_CASTLE_FLOOR_PLANS })\n                    end\n                end,\n\n                onTrigger = quest:event(647, { [1] = xi.item.COPY_OF_THE_CASTLE_FLOOR_PLANS }),\n            },\n\n            onEventFinish =\n            {\n                [648] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 0)\n                    player:confirmTrade()\n                    npcUtil.giveCurrency(player, 'gil', 900)\n                    player:addFame(xi.fameArea.SANDORIA, 16)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Chasing_Quotas.lua"]={["Path"]="scripts/quests/sandoria/Chasing_Quotas.lua",["SHA256"]="ba485a1a803b97f66a4a766472b2e36d40b71c9b2ee1d693642a8fcf701a7808",["Text"]="-----------------------------------\n-- Chasing Quotas (DRG AF2)\n-----------------------------------\n-- Log ID: 0, Quest ID: 95\n-- !addquest 0 95\n-- Ceraulian : !pos 0 -8 -122 232\n-- Miaux     : !pos -169.127 2.999 158.677 231\n-- Ardea     : !pos -198 -6 -69 235\n-- Esca      : !pos -624.231 -51.499 278.369 100\n-- qm2 (???) : !pos 145.373 16.462 -548.560 105\n-----------------------------------\n-- Brugaire is mugged one minute after the gold hairpin is traded to Ceraulian.\n-- The ??? grants Ranchuriome's legacy on the first click after Sturmtiger dies.\n-----------------------------------\nlocal batalliaID = zones[xi.zone.BATALLIA_DOWNS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.CHASING_QUOTAS)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.DRACHEN_BRAIS,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.A_CRAFTSMANS_WORK)\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Ceraulian'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainJob() ~= xi.job.DRG or\n                        player:getMainLvl() < xi.settings.main.AF2_QUEST_LEVEL\n                    then\n                        return\n                    end\n\n                    if quest:getVar(player, 'Declined') == 0 then\n                        return quest:progressEvent(18)\n                    end\n\n                    return quest:progressEvent(14)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [14] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Declined', 0)\n                        quest:begin(player)\n                    end\n                end,\n\n                [18] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Declined', 1)\n                    elseif option ~= utils.EVENT_CANCELLED_OPTION then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Ardea'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 3 then\n                        return quest:progressEvent(264)\n                    elseif progress == 4 then\n                        return quest:event(265) -- Reminder: return the earring to Esca.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [264] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.BATALLIA_DOWNS] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Killed') == 1 then\n                        quest:setVar(player, 'Prog', 6)\n                        quest:setVar(player, 'Killed', 0)\n                        return quest:keyItem(xi.keyItem.RANCHURIOMES_LEGACY)\n                    end\n\n                    -- Retail sends both lines as speakerless npc text (flag unset, type 6).\n                    if\n                        quest:getVar(player, 'Prog') == 5 and\n                        npcUtil.popFromQM(player, npc, batalliaID.mob.STURMTIGER, { hide = 0 })\n                    then\n                        player:messageText(npc, batalliaID.text.SENSE_AN_EVIL_PRESENCE, false, 6)\n                    else\n                        player:messageText(npc, batalliaID.text.SOMEONE_DUG, false, 6)\n                    end\n\n                    return quest:noAction()\n                end,\n            },\n\n            ['Sturmtiger'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        quest:setVar(player, 'Killed', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Miaux'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 2 then\n                        return quest:progressEvent(67)\n                    elseif progress == 3 or progress == 4 then\n                        return quest:event(68)\n                    elseif progress == 5 or progress == 6 then\n                        return quest:event(66)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [67] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SHINY_EARRING)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Ceraulian'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        npcUtil.tradeMatches(trade, { { xi.item.GOLD_HAIRPIN, 1 } })\n                    then\n                        return quest:progressEvent(17)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:event(13) -- Reminder: bring the gold hairpin.\n                    elseif progress == 1 then\n                        if GetSystemTime() < quest:getVar(player, 'Wait') then\n                            return quest:event(3) -- Nothing new until the wait passes.\n                        end\n\n                        return quest:progressEvent(7)\n                    elseif progress == 2 then\n                        return quest:event(8) -- Reminder: investigate the mugging.\n                    elseif progress == 3 then\n                        return quest:event(6) -- Optional. Ceraulian sizes up the earring.\n                    elseif progress == 4 or progress == 5 then\n                        return quest:event(9) -- Nothing new until the armor is recovered.\n                    elseif progress == 6 then\n                        return quest:progressEvent(15)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [15] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.RANCHURIOMES_LEGACY)\n                    end\n                end,\n\n                [17] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Prog', 1)\n                    quest:setVar(player, 'Wait', GetSystemTime() + 60) -- 1 minute wait time.\n                end,\n            },\n        },\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Esca'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 4 then\n                        return quest:progressEvent(137)\n                    elseif progress == 5 then\n                        return quest:event(138) -- Reminder: the armor is buried past the Eldieme Necropolis.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [137] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.SHINY_EARRING)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Distant_Loyalties.lua"]={["Path"]="scripts/quests/sandoria/Distant_Loyalties.lua",["SHA256"]="71c8fe64dcdc6cdb972806c97a1d337b8359167d26178eb79d6400844057479b",["Text"]="-----------------------------------\n-- Distant Loyalties\n-----------------------------------\n-- Log ID: 0, Quest ID: 74\n-----------------------------------\n-- !addquest 0 74\n-- Southern San 'dOria !zone 230\n-- Femitte: !pos -17.7129 2.1000 10.1636\n-- Bastok Markets !zone 235\n-- Michea: !pos -299.2114 -15.9717 -156.0629\n-- Mythril Ingot !giveitem 653\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.DISTANT_LOYALTIES)\n\nquest.reward =\n{\n    fame     = 40,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.WHITE_CAPE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 4\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Femitte'] =\n            {\n                onTrigger = quest:progressEvent(663),\n            },\n\n            onEventFinish =\n            {\n                [663] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.GOLDSMITHING_ORDER)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Femitte'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    if\n                        questProgress == 3 and\n                        player:hasKeyItem(xi.keyItem.MYTHRIL_HEARTS)\n                    then\n                        return quest:progressEvent(665)\n                    end\n                end,\n            },\n\n            -- Dialogue will repeat until the quest is completed.\n            ['Rouva'] = quest:event(664),\n\n            onEventFinish =\n            {\n                [665] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        quest:setVar(player, 'finalCS', 1)\n                        player:delKeyItem(xi.keyItem.MYTHRIL_HEARTS)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Michea'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, { { xi.item.MYTHRIL_INGOT, 1 } }) and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        return quest:progressEvent(317)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if\n                        questProgress == 0 and\n                        player:hasKeyItem(xi.keyItem.GOLDSMITHING_ORDER)\n                    then\n                        return quest:progressEvent(315)\n                    elseif questProgress == 1 then\n                        return quest:event(316) -- Will repeat until the player trades the Myrthil Ingot\n                    elseif\n                        questProgress == 2 and\n                        quest:getMustZone(player)\n                    then\n                        return quest:event(320) -- Will repeat until the player zones\n                    elseif\n                        questProgress == 2 and\n                        not quest:getMustZone(player)\n                    then\n                        return quest:progressEvent(318)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [315] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.GOLDSMITHING_ORDER)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [317] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 2)\n                    quest:setMustZone(player)\n                end,\n\n                [318] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    npcUtil.giveKeyItem(player, xi.keyItem.MYTHRIL_HEARTS)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Michea'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'finalCS') == 1 then\n                        return quest:progressEvent(319)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [319] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.GOLDSMITHING_ORDER)\n                    quest:setVar(player, 'finalCS', 0)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Eco_Warrior.lua"]={["Path"]="scripts/quests/sandoria/Eco_Warrior.lua",["SHA256"]="4e1e15eb4f374e2749f934be1d69e7926a90eff13b7ebb11b8ce23d22f2903e4",["Text"]="-----------------------------------\n-- Eco-Warrior (San d'Oria)\n-----------------------------------\n-- Log ID: 0, Quest ID: 97\n-- !addquest 0 97\n-- Norejaie   : !pos 83.924 1 110.54 230\n-- Rojaireaut : !pos -91.781 -0.545 587.944 193\n-- qm7        : !pos -90 30 156 193\n-----------------------------------\n-- The indigested stalagmite alone gates the turn-in. Returning to Rojaireaut first is optional.\n-- Event 54 does not remove the level restriction. Removal stays available through event 53.\n-- Completing any nation's Eco-Warrior locks all three until the next conquest tally.\n-----------------------------------\nlocal ordellesID = zones[xi.zone.ORDELLES_CAVES]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.ECO_WARRIOR)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    gil      = 5000,\n    item     = xi.item.DRAGON_CHRONICLES,\n    title    = xi.title.VERMILLION_VENTURER,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Norejaie'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED or\n                        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED\n                    then\n                        return quest:event(682) -- Already on another nation's Eco-Warrior.\n                    elseif\n                        player:getFameLevel(xi.fameArea.SANDORIA) >= 1 and\n                        player:getCharVar('EcoReset') == 0\n                    then\n                        return quest:progressEvent(677) -- Offers the quest.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [677] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ORDELLES_CAVES] =\n        {\n            ['Necroplasm'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasStatusEffect(xi.effect.LEVEL_RESTRICTION) then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n\n            ['qm7'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        player:hasStatusEffect(xi.effect.LEVEL_RESTRICTION) and\n                        npcUtil.popFromQM(player, npc, ordellesID.mob.NECROPLASM, { claim = true, look = true, hide = 0 })\n                    then\n                        return quest:messageSpecial(ordellesID.text.OINTMENT_DRAWS_CREATURE)\n                    elseif\n                        quest:getVar(player, 'Prog') == 1 and\n                        not player:hasKeyItem(xi.keyItem.INDIGESTED_STALAGMITE)\n                    then\n                        return quest:keyItem(xi.keyItem.INDIGESTED_STALAGMITE)\n                    end\n                end,\n            },\n\n            ['Rojaireaut'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.INDIGESTED_STALAGMITE) and\n                        quest:getVar(player, 'Informed') == 0\n                    then\n                        return quest:progressEvent(54) -- Sends the player to Norejaie.\n                    elseif player:hasStatusEffect(xi.effect.LEVEL_RESTRICTION) then\n                        return quest:progressEvent(53) -- Offers to remove the ointment.\n                    elseif not player:hasKeyItem(xi.keyItem.INDIGESTED_STALAGMITE) then\n                        return quest:progressEvent(51) -- Offers to apply the ointment.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [51] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:addStatusEffect(xi.effect.LEVEL_RESTRICTION, {\n                            power    = 25,\n                            subPower = 1, -- exp uses actual level and not the restricted level.\n                            origin   = player,\n                            flag     = xi.effectFlag.ON_ZONE\n                        })\n                    end\n                end,\n\n                [53] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:delStatusEffect(xi.effect.LEVEL_RESTRICTION)\n                    end\n                end,\n\n                [54] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Informed', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Norejaie'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.INDIGESTED_STALAGMITE) then\n                        return quest:progressEvent(681) -- Completes the quest.\n                    else\n                        return quest:event(679) -- Reminder to see Rojaireaut.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [681] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.INDIGESTED_STALAGMITE)\n                        player:setCharVar('EcoReset', 1, NextConquestTally())\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Norejaie'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Repeatable after the next conquest tally.\n                    if\n                        player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED or\n                        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED\n                    then\n                        return quest:event(682) -- Already on another nation's Eco-Warrior.\n                    elseif\n                        player:getFameLevel(xi.fameArea.SANDORIA) >= 1 and\n                        player:getCharVar('EcoReset') == 0\n                    then\n                        return quest:progressEvent(677) -- Offers the quest.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [677] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.ECO_WARRIOR)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Exit_the_Gambler.lua"]={["Path"]="scripts/quests/sandoria/Exit_the_Gambler.lua",["SHA256"]="c2afb729488b0db79336f4436588c35787a86710123c77f8777534cd2848517b",["Text"]="-----------------------------------\n-- Exit the Gambler\n-----------------------------------\n-- Log ID: 0, Quest ID: 101\n-- Aurege       : !pos -156.253 11.999 253.691 231\n-- Guilberdrier : !pos -159.082 12.000 253.794 231\n-- Varchet      : !pos 116.484 -1 91.554 230\n-----------------------------------\nlocal northenSandoriaID = zones[xi.zone.NORTHERN_SAN_DORIA]\nlocal southernSandoriaID = zones[xi.zone.SOUTHERN_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.EXIT_THE_GAMBLER)\n\nquest.reward =\n{\n    fame       = 20,\n    fameArea   = xi.fameArea.SANDORIA,\n    exp        = 2000,\n    keyItem    = xi.keyItem.MAP_OF_KING_RANPERRES_TOMB,\n    title      = xi.title.DAYBREAK_GAMBLER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                vars.Stage == 0\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Aurege'] = quest:progressEvent(521),\n\n            ['Guilberdrier'] = quest:progressEvent(521),\n\n            onEventFinish =\n            {\n                [521] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Stage', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return vars.Stage == 1\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Aurege'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(516)\n                    else\n                        return quest:messageText(northenSandoriaID.text.GAMBLING_IS_THE_RUIN) -- Reminder\n                    end\n                end,\n            },\n\n            ['Guilberdrier'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(518)\n                    else\n                        return quest:messageText(northenSandoriaID.text.WHO_DOES_HE_THINK) -- Reminder\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [516] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n                [518] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Varchet'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        not quest:getMustZone(player)\n                    then\n                        return quest:event(638):oncePerZone()\n                    else\n                        return quest:event(643)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Aurege'] = quest:event(514):replaceDefault(),\n\n            ['Guilberdrier'] = quest:messageText(northenSandoriaID.text.HE_WAS_JUST_HERE):replaceDefault(),\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Varchet'] = quest:messageText(southernSandoriaID.text.NOBODY_ONE_WANTS_TO_PLAY):replaceDefault(),\n        },\n\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Father_and_Son.lua"]={["Path"]="scripts/quests/sandoria/Father_and_Son.lua",["SHA256"]="09f47a9f8ddf22279f7b15c9b3051a1048d468763189484d3a6b667e5a83b1c1",["Text"]="-----------------------------------\n-- Father and Son\n-----------------------------------\n-- Log ID: 0, Quest ID: 4\n-- Ailbeche : !pos 4 -1 24 231\n-- Exoroche : !pos 72 -1 60 230\n-- Helbort  : !pos 71 -1 65 230\n-----------------------------------\nlocal northenSandoriaID = zones[xi.zone.NORTHERN_SAN_DORIA]\nlocal southernSandoriaID = zones[xi.zone.SOUTHERN_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.FATHER_AND_SON)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item = xi.item.WILLOW_FISHING_ROD,\n    title = xi.title.LOST_CHILD_OFFICER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Exoroche'] =\n            {\n                onTrigger = function(player, npc)\n                    if math.randomInt(1, 100) < 30 then\n                        return quest:message(southernSandoriaID.text.EXOROCHE_START)\n                    else\n                        return quest:message(southernSandoriaID.text.EXOROCHE_DIALOG_OFFSET + math.randomInt(0, 5))\n                    end\n                end,\n            },\n\n            ['Helbort'] = quest:event(593):oncePerZone(),\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Ailbeche'] = quest:progressEvent(508),\n\n            onEventFinish =\n            {\n                [508] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Ailbeche'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(509)\n                    else\n                        return quest:message(northenSandoriaID.text.AILBECHE_FATHER_WHERE):progress()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [509] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Helbort'] = quest:event(593):oncePerZone(),\n\n            ['Exoroche'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(542)\n                    else\n                        return quest:message(southernSandoriaID.text.EXOROCHE_PLEASE_TELL):progress()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [542] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.SHARPENING_THE_SWORD) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Ailbeche'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasTitle(xi.title.FAMILY_COUNSELOR) and\n                        npcUtil.tradeHasExactly(trade, xi.item.WILLOW_FISHING_ROD)\n                    then\n                        return quest:progressEvent(61)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if player:hasTitle(xi.title.FAMILY_COUNSELOR) then\n                        return quest:message(northenSandoriaID.text.AILBECHE_WHEN_FISHING):replaceDefault()\n                    else\n                        npc:showText(npc, northenSandoriaID.text.OH_I_WANT_MY_ITEM, xi.item.WILLOW_FISHING_ROD)\n                        return quest:noAction():progress()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [61] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:addTitle(xi.title.FAMILY_COUNSELOR)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Fear_of_the_Dark.lua"]={["Path"]="scripts/quests/sandoria/Fear_of_the_Dark.lua",["SHA256"]="913089cc6d2340cdd365deac9b926b5f96582f8deaa89e2bc53321914fa69dd1",["Text"]="-----------------------------------\n-- Fear of the Dark\n-----------------------------------\n-- Log ID: 0, Quest ID: 78\n-----------------------------------\n-- Secodiand : !pos -160 -0 137 231\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.FEAR_OF_THE_DARK)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.SANDORIA,\n    gil      = 200,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Secodiand'] = quest:progressEvent(19),\n\n            onEventFinish =\n            {\n                [19] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Secodiand'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.BAT_WING, 2 } }) then\n                        return quest:progressEvent(18)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [18] = function(player, csid, option, npc)\n                    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.FEAR_OF_THE_DARK) == xi.questStatus.QUEST_ACCEPTED then\n                        quest:complete(player)\n                    else\n                        npcUtil.giveCurrency(player, 'gil', 200)\n                        player:addFame(xi.fameArea.SANDORIA, 10)\n                    end\n\n                    player:confirmTrade()\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Grave_Concerns.lua"]={["Path"]="scripts/quests/sandoria/Grave_Concerns.lua",["SHA256"]="463e3e7fd65cff1318950fd656c86d8559417213d1c17818cad114794067b62c",["Text"]="-----------------------------------\n-- Grave_Concerns\n-----------------------------------\n-- Log ID: 0, Quest ID: 11\n-- !addquest 0 11\n-- !additem 547 -- tomb guards waterskin\n-- !additem 567 -- skin of well water\n-- Andecia : !pos 167 0 45 230\n-- Tombstone_Upper : !pos 1 0.1 -101 190\n-- Well : !pos -129 -6 92 230\n-----------------------------------\nlocal sandoriaID = zones[xi.zone.SOUTHERN_SAN_DORIA]\nlocal krtID      = zones[xi.zone.KING_RANPERRES_TOMB]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.GRAVE_CONCERNS)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    gil      = 560,\n    title    = xi.title.ROYAL_GRAVE_KEEPER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 1\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Andecia'] = function(player, npc)\n                local introduction = quest:getVar(player, 'Introduction')\n\n                if introduction == 0 then\n                    return quest:progressEvent(540)\n                elseif introduction == 1 then\n                    return quest:progressEvent(541)\n                end\n            end,\n\n            onEventFinish =\n            {\n                [540] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Introduction', 1)\n                end,\n\n                [541] = function(player, csid, option, npc)\n                    if option == 0 then\n                        if npcUtil.giveItem(player, xi.item.SKIN_OF_WELL_WATER) then\n                            quest:begin(player)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Andecia'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.TOMB_GUARDS_WATERSKIN) and\n                        quest:getVar(player, 'OfferingWaterOK') == 1\n                    then\n                        local droppedWaterskin = quest:getVar(player, 'DroppedWaterskin')\n\n                        if droppedWaterskin == 0 then\n                            return quest:progressEvent(558) -- I thank you adventurer (first ending)\n                        elseif droppedWaterskin == 1 then\n                            return quest:progressEvent(624) -- Well you lost the waterskin (second ending)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local offeringOK = quest:getVar(player, 'OfferingWaterOK')\n\n                    if offeringOK == 0 then\n                        if player:hasItem(xi.item.SKIN_OF_WELL_WATER) then\n                            return quest:message(sandoriaID.text.TO_GET_TO_KING_RANPERRES) -- To get to King Ranperres... (regular reminder)\n                        elseif quest:getVar(player, 'DroppedWaterskin') == 1 then\n                            return quest:event(623) -- take skin from grave, fill and return (dropped item reminder)\n                        else\n                            quest:setVar(player, 'DroppedWaterskin', 1)\n\n                            return quest:progressEvent(622) -- You lost the skin? Go get another one and fill it\n                        end\n                    elseif offeringOK == 1 then\n                        return quest:message(sandoriaID.text.TO_GET_TO_KING_RANPERRES) -- To get to King Ranperres... (regular reminder)\n                    end\n                end,\n            },\n\n            ['Well'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'OfferingWaterOK') == 1 then\n                        return quest:message(sandoriaID.text.DONT_NEED_MORE_WATER) -- You don't need more water\n                    elseif\n                        not player:hasItem(xi.item.SKIN_OF_WELL_WATER) and\n                        npcUtil.tradeHasExactly(trade, xi.item.TOMB_GUARDS_WATERSKIN)\n                    then\n                        if npcUtil.giveItem(player, xi.item.SKIN_OF_WELL_WATER) then\n                            player:tradeComplete()\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:message(sandoriaID.text.YOU_FIND_A_WELL) -- You find a well\n                end,\n            },\n\n            onEventFinish =\n            {\n                [558] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n\n                [624] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.KING_RANPERRES_TOMB] =\n        {\n\n            ['Tombstone_Upper'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'OfferingWaterOK') == 0 and\n                        trade:hasItemQty(xi.item.SKIN_OF_WELL_WATER, 1)\n                    then\n                        if npcUtil.giveItem(player, xi.item.TOMB_GUARDS_WATERSKIN) then\n                            player:tradeComplete()\n                            quest:setVar(player, 'OfferingWaterOK', 1)\n\n                            return quest:messageSpecial(krtID.text.CHANGE_WATER) -- You change the water\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local offeringOK = quest:getVar(player, 'OfferingWaterOK')\n\n                    if\n                        player:hasItem(xi.item.SKIN_OF_WELL_WATER) and\n                        offeringOK == 0 and\n                        quest:getVar(player, 'DroppedWaterskin') == 0\n                    then\n                        return quest:progressEvent(2) -- A waterskin is lying here\n                    elseif\n                        not player:hasItem(xi.item.SKIN_OF_WELL_WATER) and\n                        not player:hasItem(xi.item.TOMB_GUARDS_WATERSKIN) and\n                        offeringOK == 0\n                    then\n                        quest:setVar(player, 'DroppedWaterskin', 1)\n\n                        return quest:progressEvent(2) -- A waterskin is lying here\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    if\n                        quest:getVar(player, 'DroppedWaterskin') == 1 and\n                        not player:hasItem(xi.item.SKIN_OF_WELL_WATER)\n                    then\n                        npcUtil.giveItem(player, xi.item.TOMB_GUARDS_WATERSKIN)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Andecia'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:message(sandoriaID.text.I_THANK_YOU_ADVENTURER)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Grimy_Signposts.lua"]={["Path"]="scripts/quests/sandoria/Grimy_Signposts.lua",["SHA256"]="87f4a0cac44901191e3c6d73e838dc567cd6bc1ed2114db065ad9836782ac5c2",["Text"]="-----------------------------------\n-- Grimy Signposts\n-----------------------------------\n-- Log ID: 0, Quest ID: 66\n-----------------------------------\n-- Maugie    : !pos 105 2 -16 230\n-- Signpost  : !pos 301 0 419 104\n-- Signpost  : !pos -457 2 -416 104\n-- Signpost  : !pos -260 0 -23 104\n-- Signpost  : !pos -73 2 100 104\n-----------------------------------\nlocal ID = zones[xi.zone.JUGNER_FOREST]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.GRIMY_SIGNPOSTS)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    gil      = 1500,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 2\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Maugie'] = quest:progressEvent(45),\n\n            onEventFinish =\n            {\n                [45] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog < 15\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Maugie'] = quest:event(43),\n        },\n\n        [xi.zone.JUGNER_FOREST] =\n        {\n            ['Signpost'] =\n            {\n                onTrigger = function(player, npc)\n                    local info =\n                    {\n                        [0] = 9,\n                        [1] = 8,\n                        [2] = 7,\n                        [3] = 6,\n                    }\n                    local offset = npc:getID() - ID.npc.SIGNPOST[1]\n                    local data = info[offset]\n\n                    if data and not quest:isVarBitsSet(player, 'Prog', data - 6) then\n                        return quest:progressCutscene(data, 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [6] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:messageSpecial(ID.text.SIGNPOST_NEW)\n                        quest:setVarBit(player, 'Prog', 0)\n                    end\n                end,\n\n                [7] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:messageSpecial(ID.text.SIGNPOST_NEW)\n                        quest:setVarBit(player, 'Prog', 1)\n                    end\n                end,\n\n                [8] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:messageSpecial(ID.text.SIGNPOST_NEW)\n                        quest:setVarBit(player, 'Prog', 2)\n                    end\n                end,\n\n                [9] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:messageSpecial(ID.text.SIGNPOST_NEW)\n                        quest:setVarBit(player, 'Prog', 3)\n                    end\n                end,\n            }\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n            vars.Prog == 15\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Maugie'] = quest:progressEvent(44),\n\n            onEventFinish =\n            {\n                [44] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Maugie'] = quest:event(42):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"}};
